const CACHE_NAME="eabsen-v6.1.124",ASSETS_TO_CACHE=["./index.html","./js/app.min.js","./icons/icon-192.png","./icons/icon-512.png","./css/tailwinds.min.css","./css/bootstrap-icons.css","./css/fonts/bootstrap-icons.woff","./css/fonts/bootstrap-icons.woff2","./js/sweetalert2.all.min.js","./js/html5-qrcode.min.js","./js/qrcode.min.js","./js/localforage.min.js"];self.addEventListener("install",t=>{t.waitUntil(caches.open(CACHE_NAME).then(e=>e.addAll(ASSETS_TO_CACHE)))}),self.addEventListener("activate",t=>{t.waitUntil(caches.keys().then(e=>Promise.all(e.map(s=>{if(s!==CACHE_NAME)return caches.delete(s)}))).then(()=>self.clients.claim()))});function getScopePath(){try{const t=new URL(self.registration.scope).pathname;return t.endsWith("/")?t:t+"/"}catch(t){return"/"}}self.addEventListener("fetch",t=>{const e=new URL(t.request.url),s=getScopePath();if(e.pathname.endsWith("/manifest.json")){t.respondWith(fetch(t.request));return}if(e.pathname.startsWith(s+"api/")){t.respondWith(fetch(t.request).catch(()=>new Response(JSON.stringify({error:"Server down"}),{status:503,headers:{"Content-Type":"application/json"}})));return}if(t.request.mode==="navigate"&&(e.pathname===s||e.pathname.endsWith("/index.html"))){t.respondWith(caches.match("./index.html").then(r=>r||fetch("./index.html")));return}t.respondWith(caches.match(t.request).then(r=>r||fetch(t.request).then(n=>{if(!n||n.status!==200||n.type!=="basic"&&n.type!=="cors")return n;const i=n.clone();return caches.open(CACHE_NAME).then(c=>{c.put(t.request,i).catch(()=>{})}),n}).catch(()=>new Response("",{status:504,statusText:"Gateway Timeout"}))))}),self.addEventListener("message",t=>{const e=t.data;if(e){if(e.type==="SKIP_WAITING"){self.skipWaiting();return}e.type==="GET_VERSION"&&(t.ports&&t.ports[0]?t.ports[0].postMessage({version:CACHE_NAME}):self.clients.matchAll().then(s=>{s.forEach(a=>a.postMessage({type:"SW_VERSION",version:CACHE_NAME}))}))}});
